------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
	output = "",
	mode = "preferred",
	position = "auto",
	scale = "1.1",
})

---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal = "kitty"
local fileManager = "nemo"
local menu = "hyprlauncher"
local browser = "firefox"
local editor = "code-oss"

-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function()
	hl.exec_cmd("dms run >/dev/null 2>&1")
	-- hl.exec_cmd("nwg-dock-hyprland -x -d -i 48 -p bottom")
	-- cinnamon-schema-mirror (mirrors org.gnome.desktop.interface ->
	-- org.cinnamon.desktop.interface live, so Nemo picks up theme changes
	-- without needing a restart) runs as its own systemd --user service now,
	-- not launched from here -- it kept dying under `dms restart` (which uses
	-- loginctl and appears to affect more than just its own process), and a
	-- plain setsid-detached exec_cmd here has no supervision to recover from
	-- that. systemd's Restart=always does. See
	-- ~/.config/systemd/user/cinnamon-schema-mirror.service.
end)

