--------------------------------------------------------
---- TILING (omarchy: default/hypr/bindings/tiling.lua) ----
--------------------------------------------------------
hl.bind(mainMod .. " + W", hl.dsp.window.close(), { description = "Close window" })
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close(), { description = "Close window" })
-- closeWindowBind:set_enabled(false)

hl.bind(mainMod .. " + P", hl.dsp.window.pseudo(), { description = "Pseudo window" })
hl.bind(
	mainMod .. " + ALT + SPACE",
	hl.dsp.window.float({ action = "toggle" }),
	{ description = "Toggle window floating/tiling" }
)
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }), { description = "Full screen" })
hl.bind(mainMod .. " + ALT + F", hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Full width" })
hl.bind(mainMod .. " + J", hl.dsp.layout("swapprev"), { description = "Swap to previous window (master)" })
hl.bind(mainMod .. " + K", hl.dsp.layout("swapnext"), { description = "Swap to next window (master)" })
hl.bind(mainMod .. " + I", hl.dsp.layout("orientationtop"), { description = "Master orientation: top" })
hl.bind(mainMod .. " + O", hl.dsp.layout("orientationcenter"), { description = "Master orientation: center" })
hl.bind(mainMod .. " + U", hl.dsp.layout("orientationleft"), { description = "Master orientation: left" })

-- Switch to a submap called `resize`.
hl.bind("ALT + mouse:272", hl.dsp.submap("resize"), { mouse = true, description = "Resize window (drag)" })

-- Start a submap called "resize".
hl.define_submap("resize", function()
	-- Set repeating binds for resizing the active window.
	hl.bind(
		"D",
		hl.dsp.window.resize({ x = 10, y = 0, relative = true }),
		{ repeating = true, description = "Grow width" }
	)
	hl.bind(
		"A",
		hl.dsp.window.resize({ x = -10, y = 0, relative = true }),
		{ repeating = true, description = "Shrink width" }
	)
	hl.bind(
		"W",
		hl.dsp.window.resize({ x = 0, y = 10, relative = true }),
		{ repeating = true, description = "Grow height" }
	)
	hl.bind(
		"S",
		hl.dsp.window.resize({ x = 0, y = -10, relative = true }),
		{ repeating = true, description = "Shrink height" }
	)

	-- Use `reset` to go back to the global submap
	hl.bind("escape", hl.dsp.submap("reset"), { description = "Exit resize mode" })
end)

-- Keybinds further down will be global again...

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }), { description = "Focus on left window" })
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus on right window" })
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }), { description = "Focus on above window" })
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }), { description = "Focus on below window" })

-- Swap window position in the given direction (omarchy: SUPER + SHIFT + arrow)
hl.bind(
	mainMod .. " + SHIFT + left",
	hl.dsp.window.swap({ direction = "l" }),
	{ description = "Swap window to the left" }
)
hl.bind(
	mainMod .. " + SHIFT + right",
	hl.dsp.window.swap({ direction = "r" }),
	{ description = "Swap window to the right" }
)
hl.bind(mainMod .. " + SHIFT + up", hl.dsp.window.swap({ direction = "u" }), { description = "Swap window up" })
hl.bind(mainMod .. " + SHIFT + down", hl.dsp.window.swap({ direction = "d" }), { description = "Swap window down" })

-- Move the whole workspace to the monitor in the given direction
hl.bind(
	mainMod .. " + SHIFT + ALT + left",
	hl.dsp.workspace.move({ monitor = "l" }),
	{ description = "Move workspace to left monitor" }
)
hl.bind(
	mainMod .. " + SHIFT + ALT + right",
	hl.dsp.workspace.move({ monitor = "r" }),
	{ description = "Move workspace to right monitor" }
)
hl.bind(
	mainMod .. " + SHIFT + ALT + up",
	hl.dsp.workspace.move({ monitor = "u" }),
	{ description = "Move workspace to up monitor" }
)
hl.bind(
	mainMod .. " + SHIFT + ALT + down",
	hl.dsp.workspace.move({ monitor = "d" }),
	{ description = "Move workspace to down monitor" }
)

-- Window grouping (tabbed windows)
hl.bind(mainMod .. " + G", hl.dsp.group.toggle(), { description = "Toggle window grouping" })
hl.bind(
	mainMod .. " + ALT + G",
	hl.dsp.window.move({ out_of_group = true }),
	{ description = "Move active window out of group" }
)
hl.bind(
	mainMod .. " + ALT + left",
	hl.dsp.window.move({ into_group = "l" }),
	{ description = "Move window to group on left" }
)
hl.bind(
	mainMod .. " + ALT + right",
	hl.dsp.window.move({ into_group = "r" }),
	{ description = "Move window to group on right" }
)
hl.bind(
	mainMod .. " + ALT + up",
	hl.dsp.window.move({ into_group = "u" }),
	{ description = "Move window to group on top" }
)
hl.bind(
	mainMod .. " + ALT + down",
	hl.dsp.window.move({ into_group = "d" }),
	{ description = "Move window to group on bottom" }
)
hl.bind(mainMod .. " + CTRL + left", hl.dsp.group.prev(), { description = "Move grouped window focus left" })
hl.bind(mainMod .. " + CTRL + right", hl.dsp.group.next(), { description = "Move grouped window focus right" })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
-- Move it there silently (without following) with mainMod + SHIFT + ALT + [0-9]
for i = 1, 10 do
	local key = i % 10 -- 10 maps to key 0
	hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }), { description = "Switch to workspace " .. i })
	hl.bind(
		mainMod .. " + SHIFT + " .. key,
		hl.dsp.window.move({ workspace = i }),
		{ description = "Move window to workspace " .. i }
	)
	hl.bind(
		mainMod .. " + SHIFT + ALT + " .. key,
		hl.dsp.window.move({ workspace = i, follow = false }),
		{ description = "Move window silently to workspace " .. i }
	)
end

-- Cycle workspaces (omarchy: TAB / SHIFT+TAB / CTRL+TAB)
hl.bind(mainMod .. " + TAB", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(mainMod .. " + SHIFT + TAB", hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })
hl.bind(mainMod .. " + CTRL + TAB", hl.dsp.focus({ workspace = "previous" }), { description = "Former workspace" })

-- Cycle windows on screen (omarchy: ALT+TAB) and monitors (omarchy: CTRL+ALT+TAB)
hl.bind("ALT + TAB", hl.dsp.window.cycle_next(), { description = "Focus on next window" })
hl.bind("ALT + SHIFT + TAB", hl.dsp.window.cycle_next({ next = false }), { description = "Focus on previous window" })
hl.bind("CTRL + ALT + TAB", hl.dsp.focus({ monitor = "+1" }), { description = "Focus on next monitor" })
hl.bind("CTRL + ALT + SHIFT + TAB", hl.dsp.focus({ monitor = "-1" }), { description = "Focus on previous monitor" })

-- Scratchpad (omarchy names this special workspace "scratchpad")
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("scratchpad"), { description = "Toggle scratchpad" })
hl.bind(
	mainMod .. " + SHIFT + S",
	hl.dsp.window.move({ workspace = "special:scratchpad" }),
	{ description = "Move window to scratchpad" }
)
hl.bind(
	mainMod .. " + ALT + S",
	hl.dsp.window.move({ workspace = "special:scratchpad", follow = false }),
	{ description = "Move window to scratchpad (silently)" }
)
hl.bind(mainMod .. " + grave", hl.dsp.workspace.toggle_special("scratchpad"), { description = "Toggle scratchpad" })
hl.bind(
	mainMod .. " + SHIFT + grave",
	hl.dsp.window.move({ workspace = "special:scratchpad", follow = false }),
	{ description = "Move window to scratchpad (silently)" }
)

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(
	mainMod .. " + mouse_down",
	hl.dsp.focus({ workspace = "e+1" }),
	{ description = "Scroll active workspace forward" }
)
hl.bind(
	mainMod .. " + mouse_up",
	hl.dsp.focus({ workspace = "e-1" }),
	{ description = "Scroll active workspace backward" }
)

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true, description = "Move window" })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Resize window" })

-- Keyboard-driven resize (omarchy: SUPER/SUPER+ALT/SUPER+CTRL + code:20/21, the bracket keys)
hl.bind(
	mainMod .. " + code:20",
	hl.dsp.window.resize({ x = -100, y = 0, relative = true }),
	{ description = "Expand window left" }
)
hl.bind(
	mainMod .. " + code:21",
	hl.dsp.window.resize({ x = 100, y = 0, relative = true }),
	{ description = "Shrink window left" }
)
hl.bind(
	mainMod .. " + SHIFT + code:20",
	hl.dsp.window.resize({ x = 0, y = -100, relative = true }),
	{ description = "Shrink window up" }
)
hl.bind(
	mainMod .. " + SHIFT + code:21",
	hl.dsp.window.resize({ x = 0, y = 100, relative = true }),
	{ description = "Expand window down" }
)
hl.bind(
	mainMod .. " + ALT + code:20",
	hl.dsp.window.resize({ x = -25, y = 0, relative = true }),
	{ description = "Expand window left a little" }
)
hl.bind(
	mainMod .. " + ALT + code:21",
	hl.dsp.window.resize({ x = 25, y = 0, relative = true }),
	{ description = "Shrink window left a little" }
)
hl.bind(
	mainMod .. " + CTRL + code:20",
	hl.dsp.window.resize({ x = -300, y = 0, relative = true }),
	{ description = "Expand window left a lot" }
)
hl.bind(
	mainMod .. " + CTRL + code:21",
	hl.dsp.window.resize({ x = 300, y = 0, relative = true }),
	{ description = "Shrink window left a lot" }
)

