hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("dms ipc call launcher toggle"), { description = "App launcher" })
-- Note: DMS's "bar toggle" IPC function takes a (selector, value) pair whose
-- expected values aren't documented/discoverable via the CLI, so this omarchy
-- bind (SUPER+SHIFT+SPACE toggles the top bar) is left unwired rather than
-- shipped guessing at broken arguments.
hl.bind(
	mainMod .. " + CTRL + SPACE",
	hl.dsp.exec_cmd("dms ipc call dash toggle wallpaper"),
	{ description = "Wallpaper picker" }
)
hl.bind(mainMod .. " + CTRL + T", hl.dsp.exec_cmd("qs -n -c themeswitcher"), { description = "Theme switcher" })
hl.bind(
	mainMod .. " + CTRL + SHIFT + SPACE",
	hl.dsp.exec_cmd("qs -n -c themeswitcher"),
	{ description = "Theme switcher" }
)
hl.bind(mainMod .. " + ESCAPE", hl.dsp.exec_cmd("dms ipc call powermenu toggle"), { description = "System menu" })
hl.bind(mainMod .. " + CTRL + P", hl.dsp.exec_cmd("dms ipc call powermenu toggle"), { description = "Power menu" })
hl.bind(mainMod .. " + CTRL + L", hl.dsp.exec_cmd("dms ipc call lock lock"), { description = "Lock system" })
hl.bind(
	mainMod .. " + CTRL + V",
	hl.dsp.exec_cmd("dms ipc call clipboard toggle"),
	{ description = "Clipboard manager" }
)
hl.bind(mainMod .. " + CTRL + N", hl.dsp.exec_cmd("dms ipc call night toggle"), { description = "Toggle nightlight" })
hl.bind(
	mainMod .. " + CTRL + I",
	hl.dsp.exec_cmd("dms ipc call inhibit toggle"),
	{ description = "Toggle locking on idle" }
)
-- omarchy binds SUPER+K to its keybindings cheatsheet, but K is already taken
-- here by master-layout swapnext (see TILING section), so this uses SUPER+SHIFT+K
-- instead, opening DMS's own built-in cheatsheet (dms keybinds show hyprland),
-- which auto-reads every bind above from this config, description text included.
hl.bind(
	mainMod .. " + SHIFT + K",
	hl.dsp.exec_cmd("dms ipc call keybinds toggle hyprland"),
	{ description = "Keybindings cheatsheet" }
)

-- DMS consolidates bluetooth/network/audio/display into one control-center
-- panel, unlike omarchy's four separate bar panels, so all four omarchy keys
-- point at the same panel here.
hl.bind(
	mainMod .. " + CTRL + A",
	hl.dsp.exec_cmd("dms ipc call control-center toggle"),
	{ description = "Control center (audio)" }
)
hl.bind(
	mainMod .. " + CTRL + B",
	hl.dsp.exec_cmd("dms ipc call control-center toggle"),
	{ description = "Control center (bluetooth)" }
)
hl.bind(
	mainMod .. " + CTRL + W",
	hl.dsp.exec_cmd("dms ipc call control-center toggle"),
	{ description = "Control center (network)" }
)
hl.bind(
	mainMod .. " + CTRL + D",
	hl.dsp.exec_cmd("dms ipc call control-center toggle"),
	{ description = "Control center (display)" }
)

