--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

-- Float Firefox/Thunderbird child windows (downloads, dialogs, popups,
-- notifications) while leaving the main browser/mail window tiled. Both
-- apps' main window title always contains their app name ("Mozilla Firefox" /
-- "Mozilla Thunderbird"); every child window has some other title, so a
-- negative-lookahead on title is what tells them apart. Rules are static and
-- only ever evaluated against a window's *initial* class/title.
hl.window_rule({
	name = "float-firefox-children",
	match = { class = "^firefox$", title = "negative:Mozilla Firefox" },

	float = true,
})

hl.window_rule({
	name = "float-thunderbird-children",
	match = { class = "^org\\.mozilla\\.Thunderbird$", title = "negative:Mozilla Thunderbird" },

	float = true,
})

